package de.schaepi.puls180;
import android.content.Context;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.Locale;import javax.net.ssl.HttpsURLConnection;
public final class LicenseRevocation {
 private static final String URL="https://raw.githubusercontent.com/Kubihl/blutdruck-for-user/main/revoked-license-hashes.txt";
 private static boolean busy;private static long lastCheck;
 private static String fingerprint(String code)throws Exception{byte[] value=MessageDigest.getInstance("SHA-256").digest(("PULS180-REVOCATION|"+code).getBytes(StandardCharsets.UTF_8));StringBuilder out=new StringBuilder();for(byte b:value)out.append(String.format(Locale.ROOT,"%02X",b));return out.toString();}
 public static synchronized void checkOnOpen(Context context,Runnable finished){if(License.revoked(context)||!License.hasPermanentKey(context)){finished.run();return;}long now=android.os.SystemClock.elapsedRealtime();if(busy||now-lastCheck<30000){finished.run();return;}busy=true;Context app=context.getApplicationContext();new Thread(()->{boolean revoked=false;HttpsURLConnection connection=null;try{connection=(HttpsURLConnection)new URL(URL+"?t="+System.currentTimeMillis()).openConnection();connection.setConnectTimeout(4000);connection.setReadTimeout(4000);connection.setUseCaches(false);connection.setRequestProperty("Accept","text/plain");if(connection.getResponseCode()!=200)throw new IOException();ByteArrayOutputStream data=new ByteArrayOutputStream();try(InputStream in=connection.getInputStream()){byte[] buffer=new byte[2048];int n;while((n=in.read(buffer))!=-1){if(data.size()+n>131072)throw new IOException();data.write(buffer,0,n);}}String own=fingerprint(License.code(app));for(String line:data.toString("UTF-8").split("\\R")){String clean=line.trim().toUpperCase(Locale.ROOT);if(clean.equals(own)){revoked=true;break;}if(!clean.isEmpty()&&!clean.startsWith("#")&&!clean.matches("[A-F0-9]{64}"))throw new IOException();}if(revoked)License.markRevoked(app);}catch(Exception ignored){}finally{if(connection!=null)connection.disconnect();synchronized(LicenseRevocation.class){busy=false;lastCheck=android.os.SystemClock.elapsedRealtime();}new android.os.Handler(android.os.Looper.getMainLooper()).post(finished);}},"Puls180-Lizenzpruefung").start();}
}
